svg.script:
const FF_JS = "https:/" + "/cdn.jsdelivr.net/npm/@ffmpeg/ffmpeg@0.11.6/dist/ffmpeg.min.js";
const CORE_JS = "https:/" + "/cdn.jsdelivr.net/npm/@ffmpeg/core-st@0.11.1/dist/ffmpeg-core.js";
const DEMUX_JS = "https:/" + "/cdn.jsdelivr.net/gh/Yahweasel/mkvdemuxjs@master/mkvdemux.js";
const frame = document.getElementById("linux_frame");

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"/>
<style>
  body,html{margin:0;padding:0;background:#000;color:#eee;font-family:monospace;height:100%;display:flex;flex-direction:column;overflow:hidden}
  #bar{padding:8px;background:#1a1a1a;display:flex;gap:8px;align-items:center;border-bottom:1px solid #333;font-size:12px}
  #cv{flex:1;width:100%;height:100%;object-fit:contain;background:#000}
  #msg{margin-left:auto;color:#7f7}
</style>
<script>
  const OrigWorker = window.Worker;
  window.Worker = function(url, opts) {
    const blob = new Blob(['importScripts("' + url + '");'], { type: "application/javascript" });
    return new OrigWorker(URL.createObjectURL(blob), opts);
  };
<\/script>
<script src="${FF_JS}"><\/script>
<script src="${DEMUX_JS}"><\/script>
</head><body>
<div id="bar">
  <input type="file" id="f" accept=".mkv,.webm" disabled />
  <button id="btn">Pause</button>
  <span id="msg">Loading FFmpeg + MKVDemux...</span>
</div>
<canvas id="cv"></canvas>
<script>
  const cv = document.getElementById("cv"), ctx = cv.getContext("2d");
  const msg = document.getElementById("msg"), fileIn = document.getElementById("f");
  let play = true, runId = 0, ffmpeg = null, actx = null, nextAudioTime = 0;

  document.getElementById("btn").onclick = async () => {
    play = !play;
    document.getElementById("btn").textContent = play ? "Pause" : "Play";
    if (actx) play ? await actx.resume() : await actx.suspend();
  };

  (async () => {
    ffmpeg = FFmpeg.createFFmpeg({ corePath: "${CORE_JS}", mainName: "main", log: false });
    await ffmpeg.load();
    fileIn.disabled = false;
    msg.textContent = "Ready (Select .mkv)";
  })();

  function toAnnexB(avcC, pkt) {
    const out = [];
    if (avcC) {
      let p = 5, nSps = avcC[p++] & 31;
      for (let i = 0; i < nSps; i++) { const l = (avcC[p]<<8)|avcC[p+1]; p+=2; out.push(new Uint8Array([0,0,0,1]), avcC.subarray(p, p+l)); p+=l; }
      let nPps = avcC[p++];
      for (let i = 0; i < nPps; i++) { const l = (avcC[p]<<8)|avcC[p+1]; p+=2; out.push(new Uint8Array([0,0,0,1]), avcC.subarray(p, p+l)); p+=l; }
    }
    let p = 0;
    while (p + 4 <= pkt.length) {
      const l = (pkt[p]<<24)|(pkt[p+1]<<16)|(pkt[p+2]<<8)|pkt[p+3]; p += 4;
      if (l <= 0 || p + l > pkt.length) break;
      out.push(new Uint8Array([0,0,0,1]), pkt.subarray(p, p + l)); p += l;
    }
    const res = new Uint8Array(out.reduce((a, b) => a + b.length, 0));
    let o = 0; for (const b of out) { res.set(b, o); o += b.length; }
    return res;
  }

  function wrapAdts(raw, asc) {
    const prof = asc ? ((asc[0]>>3)-1) : 1, freq = asc ? (((asc[0]&7)<<1)|(asc[1]>>7)) : 3, ch = asc ? ((asc[1]>>3)&15) : 2;
    const len = raw.length + 7, h = new Uint8Array(len);
    h[0]=0xFF; h[1]=0xF1; h[2]=((prof&3)<<6)|((freq&15)<<2)|((ch>>2)&1);
    h[3]=((ch&3)<<6)|((len>>11)&3); h[4]=(len>>3)&0xFF; h[5]=((len&7)<<5)|0x1F; h[6]=0xFC;
    h.set(raw, 7); return h;
  }

  function playPcm(pcm, sr) {
    if (!pcm || pcm.byteLength < 16) return 0;
    if (!actx) actx = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: sr });
    const n = Math.floor(pcm.byteLength / 8), f32 = new Float32Array(pcm.buffer, pcm.byteOffset, n * 2);
    const buf = actx.createBuffer(2, n, sr), L = buf.getChannelData(0), R = buf.getChannelData(1);
    for (let i = 0; i < n; i++) { L[i] = f32[i*2]; R[i] = f32[i*2+1]; }
    const src = actx.createBufferSource(); src.buffer = buf; src.connect(actx.destination);
    const t = Math.max(actx.currentTime + 0.04, nextAudioTime); src.start(t); nextAudioTime = t + buf.duration;
    return buf.duration;
  }

  fileIn.onchange = async (e) => {
    const file = e.target.files && e.target.files.item(0);
    if (!file || !ffmpeg) return;
    const myRun = ++runId; play = true;
    msg.textContent = "Demuxing MKV...";

    const demux = new MKVDemux();
    const vFrames = [], aFrames = [];
    let vTrk = 1, aTrk = 2, vPriv = null, aPriv = null;

    demux.push(await file.arrayBuffer());
    let ev;
    while ((ev = demux.demux())) {
      if (ev.tracks) {
        for (const k in ev.tracks) {
          const t = ev.tracks[k];
          if (t.type === 1) { vTrk = t.number; vPriv = t.codecPrivate ? new Uint8Array(t.codecPrivate) : null; }
          if (t.type === 2) { aTrk = t.number; aPriv = t.codecPrivate ? new Uint8Array(t.codecPrivate) : null; }
        }
      }
      if (ev.frames) {
        for (const fr of ev.frames) {
          const d = new Uint8Array(fr.data);
          if (fr.track === vTrk) vFrames.push({ ts: fr.timestamp, key: fr.keyframe, data: d });
          else if (fr.track === aTrk) aFrames.push({ ts: fr.timestamp, data: d });
        }
      }
    }

    const W = 512, H = 288, sr = 48000;
    cv.width = W; cv.height = H;
    const imgData = ctx.createImageData(W, H);
    if (!actx) actx = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: sr });
    nextAudioTime = actx.currentTime;

    let idx = 0, drawn = 0;
    while (myRun === runId && idx < vFrames.length) {
      if (!play) { await new Promise(r => setTimeout(r, 50)); continue; }
      let endIdx = Math.min(vFrames.length, idx + 72);
      while (endIdx < vFrames.length && !vFrames[endIdx].key && (endIdx - idx) < 240) endIdx++;

      const t0 = vFrames[idx].ts, t1 = endIdx < vFrames.length ? vFrames[endIdx].ts : (t0 + 3);
      const vChunks = vFrames.slice(idx, endIdx).map((f, k) => toAnnexB(k === 0 ? vPriv : null, f.data));
      const vBuf = new Uint8Array(vChunks.reduce((a, b) => a + b.length, 0));
      let o = 0; for (const c of vChunks) { vBuf.set(c, o); o += c.length; }

      const aChunks = aFrames.filter(f => f.ts >= t0 && f.ts < t1).map(f => wrapAdts(f.data, aPriv));
      const aBuf = new Uint8Array(aChunks.reduce((a, b) => a + b.length, 0));
      o = 0; for (const c of aChunks) { aBuf.set(c, o); o += c.length; }

      ffmpeg.FS("writeFile", "v.h264", vBuf);
      const args = ["-r", "23.976", "-f", "h264", "-i", "v.h264"];
      if (aBuf.length) { ffmpeg.FS("writeFile", "a.aac", aBuf); args.push("-f", "aac", "-i", "a.aac"); }
      args.push("-map", "0:v:0", "-vf", "scale=" + W + ":" + H, "-f", "rawvideo", "-pix_fmt", "rgba", "out.rgba");
      if (aBuf.length) args.push("-map", "1:a:0", "-ac", "2", "-ar", "48000", "-f", "f32le", "out.pcm");

      try { await ffmpeg.run(...args); } catch (_) {}
      try { ffmpeg.FS("unlink", "v.h264"); ffmpeg.FS("unlink", "a.aac"); } catch (_) {}

      let raw = null, pcm = null;
      try { raw = ffmpeg.FS("readFile", "out.rgba"); ffmpeg.FS("unlink", "out.rgba"); } catch (_) {}
      try { pcm = ffmpeg.FS("readFile", "out.pcm"); ffmpeg.FS("unlink", "out.pcm"); } catch (_) {}

      const fBytes = W * H * 4, total = raw ? Math.floor(raw.length / fBytes) : 0;
      if (total > 0 && myRun === runId) {
        const dur = playPcm(pcm, sr);
        const delay = dur > 0 ? Math.max(15, (dur * 1000) / total) : 41.7;
        for (let i = 0; i < total && myRun === runId; i++) {
          while (!play && myRun === runId) await new Promise(r => setTimeout(r, 50));
          imgData.data.set(raw.subarray(i * fBytes, (i + 1) * fBytes));
          ctx.putImageData(imgData, 0, 0);
          drawn++;
          if (drawn % 5 === 1) msg.textContent = "Playing: Frame " + drawn + "/" + vFrames.length;
          await new Promise(r => setTimeout(r, delay));
        }
      }
      idx = endIdx;
    }
    if (myRun === runId) msg.textContent = "Finished (" + drawn + " frames)";
  };
<\/script></body></html>`;

const doc = frame.contentDocument || frame.contentWindow.document;
doc.open(); doc.write(html); doc.close();
